import { MessageChannelFactory, BaseMessageChannel } from '../message-channels';
import { IGameChildEvents, IOperatorParentEvents, IAuthenticatePayload, GetMessageEvent, IKeyboardStatePayload, ISessionInfoPayload, IOpenSubGamePayload, IOpenSubGameUrlPayload } from '../types';

export class OperatorConnection implements IGameChildEvents {
    private messageChannel: BaseMessageChannel<IGameChildEvents, IOperatorParentEvents>;
    private handlers: IOperatorParentEvents;

    constructor(handlers: IOperatorParentEvents) {
        this.handlers = handlers;
    }

    public setKeyboardState(payload: IKeyboardStatePayload): void {
        this.messageChannel.send('setKeyboardState', payload);
    }

    public init(iframe: HTMLIFrameElement, url: string) {
        iframe.src = url;

        this.messageChannel = MessageChannelFactory.create({
            type: 'web',
            target: iframe,
            source: 'operator',
            onMessageCallback: (event) => this.onMessage(event)
        });
    }

    public async authenticate(payload: IAuthenticatePayload) {
        const authResponse = await this.messageChannel.makeRequest('authenticate', payload, 'onAuthenticated', 'game');
        await this.messageChannel.waitForResponse('onLoaded', 'game');

        return authResponse;
    }

    public async getSessionInfo() {
        return this.messageChannel.makeRequest('getSessionInfo', void 0, 'onSessionInfo', 'game');
    }

    public onSessionInfo(payload: ISessionInfoPayload): void {
        this.messageChannel.send('onSessionInfo', payload);
    }

    public openSubGame(payload: IOpenSubGamePayload): void {
        this.messageChannel.send('openSubGame', payload);
    }

    public openSubGameUrl(payload: IOpenSubGameUrlPayload): void {
        this.messageChannel.send('openSubGameUrl', payload);
    }
    
    public requestAction(payload: { action: 'openSettings' | 'closeSettings'; }): void {
        return this.messageChannel.send('requestAction', payload);
    }

    public disconnect() {
        this.messageChannel.send('disconnect', void 0);
    }

    private onMessage(event: GetMessageEvent<IOperatorParentEvents, keyof IOperatorParentEvents>) {
        if (this.handlers[event.data.type]) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            this.handlers[event.data.type](event.data.payload as any);
        }
    }

}
